const filtersDetail = await browserjs(tabId, () => {
  const container = document.querySelector('.pet-search-filters-container');
  if (!container) return { found: false };

  // Let's get all headings/sections inside the filter container
  const sections = Array.from(container.querySelectorAll('h2, h3, h4, h5, h6, label, [class*="title"], [class*="header"], [class*="section"]')).map(el => el.innerText?.trim()).filter(Boolean);

  // Let's get all checkboxes
  const checkboxes = Array.from(container.querySelectorAll('input[type="checkbox"]')).map(cb => ({
    id: cb.id,
    name: cb.name,
    value: cb.value,
    checked: cb.checked,
    label: cb.closest('label')?.innerText?.trim() || cb.parentElement?.innerText?.trim()
  }));

  // Let's get all dropdowns or buttons
  const buttons = Array.from(container.querySelectorAll('button')).map(b => b.innerText?.trim()).filter(Boolean);

  return {
    found: true,
    sections: [...new Set(sections)],
    checkboxes,
    buttons
  };
});

console.log("Filters Detail:", JSON.stringify(filtersDetail, null, 2));

