  const details = Array.from(document.querySelectorAll('[class*="detail"], [class*="fact"], [class*="info"], [class*="summary"], dl, tr, li, p')).map(el => el.innerText?.trim()).filter(Boolean);

  // Look for shelter/rescue info
  const shelter = Array.from(document.querySelectorAll('a[href*="/shelter/"], [class*="shelter"], [class*="rescue"], [class*="organization"]')).map(el => ({
    text: el.innerText?.trim(),
    href: el.href
  }));

  // Look for pet facts (breed, sex, age, color, etc.)
  const petFacts = document.querySelector('[data-testid*="pet-fact"], [class*="pet-fact"], [class*="pet-info"], .pet-details')?.innerText;

  return {
    url: window.location.href,
    name,
    petFacts,
    bodyText: document.body.innerText.slice(0, 4000)
  };
});

